pub interface Container {
  type Element;
  fn get(self: &Self, index: Int) -> Option[Self::Element];
  fn len(self: &Self) -> Int;
}

impl Container for Vec[T] {
  type Element = T;
  fn get(self: &Vec[T], index: Int) -> Option[T] {
    if index >= 0 && index < self.len() { return Some(self[index]); }
    return None();
  }
  fn len(self: &Vec[T]) -> Int { return self.len(); }
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(3);
  return v.len();
}
